const arrow=(x,y,dx,dy,color='#94dfe1')=>`<path d="M${x},${y} l${dx},${dy}" stroke="${color}" fill="none" stroke-width="5" marker-end="url(#${color==='#efb96c'?'gold':'cyan'})"/>`;
const metric=(name,value,meaning)=>({name,value,meaning});
let a06CoverNode=null;
let memoKey="",memoResult;function cached(fn,params){const key=C.id+JSON.stringify(params);if(key!==memoKey){memoKey=key;memoResult=fn(params);}return memoResult;}
function calculate(params=p,t=time){if(window.ExtraModels?.[C.id])return cached(window.ExtraModels[C.id],params);switch(C.id){case'A01':return M.grip(params);case'A09':return M.snow(params);case'C01':return M.echo(params);case'D01':return t===time&&params===p?M.heat(params,thermal,0):M.heat(params,{core:40,bill:32},t);case'E01':return cached(M.spring,params);case'E05':return M.silk(params);case'F03':return t===time&&params===p?M.dam(params,water,0):M.dam(params,undefined,t);case'H07':return cached(M.survey,params);case'A11':return cached(M.foot,params);case'B07':return M.feed(params);}}
function info(r,params=p,viewPhase=phase){if(window.LabExtension)return window.LabExtension.info(C.id,r,params,{T,L,f,metric,phase:viewPhase,running,done});switch(C.id){case'A01':return {metrics:[metric(T('抓地上限','Grip limit'),`${f(r.limit,0)} N`,T('地面最多能傳遞的力','Maximum force passed by ground')),metric(T('實際推力','Delivered force'),`${f(r.force,0)} N`,T('超過的推力變成滑移','Surplus push causes slipping')),metric(T('加速度','Acceleration'),`${f(r.a,2)} m/s²`,T('每秒增加多少速度','Speed added each second'))],explain:r.slip?T(`推力 ${p.push} N 超過上限，腳掌打滑；再用力，這個模型的加速度也不會增加。`,`Push ${p.push} N exceeds the limit: the paw slips. More push no longer raises acceleration in this model.`):T('現在抓得住！試著加大推力找到打滑的門檻，再換地面比較。','Holding grip. Increase the push to find the slip threshold, then change the ground.')};
case'A09':return {metrics:[metric(T('平均壓力','Mean pressure'),`${f(r.pressure,2)} kPa`,T('每平方米承受的力','Force per square metre')),metric(T('重量','Weight force'),`${f(r.load,0)} N`,T('質量 × 重力加速度','Mass × gravity')),metric(T('雪地反應','Snow response'),r.above?T('超過閾值','Over threshold'):T('未超過','Below threshold'),T('只表示陷入傾向','Sinking tendency only'))],explain:r.above?T('壓力超過雪的示例閾值，腳掌在圖中陷入；擴大面積或換結實的雪再試。','Pressure exceeds the example threshold, so the paw sinks in the illustration. Increase area or strengthen the snow.'):T('壓力低於雪的示例閾值。保持質量，試著把面積減半，壓力會變成兩倍。','Pressure is below the example threshold. Halve area at the same mass: pressure doubles.')};
case'C01':return {metrics:[metric(T('回聲往返時間','Echo round-trip time'),`${f(r.time*1000,1)} ms`,T('毫秒＝千分之一秒','ms = thousandth of a second')),metric(T('聲速','Sound speed'),`${f(r.c,1)} m/s`,T('每秒前進的公尺數','Metres travelled each second')),metric(T('揭曉距離','Revealed distance'),done?`${f(params.distance,1)} m`:T('發射後揭曉','Send to reveal'),done?T(`猜測誤差 ${f(r.error,1)} m`,`Guess error ${f(r.error,1)} m`):T('回聲時間 × 聲速 ÷ 2','Echo time × sound speed ÷ 2'))],explain:done?T(`這一趟共走 ${f(params.distance*2,1)} m，障礙在 ${f(params.distance,1)} m；你的猜測相差 ${f(r.error,1)} m。再移動障礙，看看時間怎麼變。`,`Total path: ${f(params.distance*2,1)} m. Obstacle: ${f(params.distance,1)} m. Your guess differs by ${f(r.error,1)} m. Move it and compare.`):T('先選一個距離、猜猜回聲會多久，再發射。動畫把往返放慢 40 倍。','Choose a distance, predict the delay, then send a pulse. The round trip is slowed 40×.')};
case'D01':return {metrics:[metric(T('核心溫度','Core temperature'),`${f(r.core,2)} °C`,T('示例核心熱庫','Illustrative core heat store')),metric(T('嘴巴溫度','Bill temperature'),`${f(r.bill,2)} °C`,T('不是實測體溫','Not a measured body temperature')),metric(T('嘴巴向外熱流','Outward bill heat flow'),`${f(r.out,2)} W`,r.out>=0?T('正值：向空氣散熱','Positive: heat leaves'):T('負值：從空氣吸熱','Negative: heat enters'))],explain:r.out<0?T('空氣比嘴巴熱，熱從空氣進入嘴巴。把風加大，吸熱也可能變快！','Air is warmer than the bill, so heat enters it. Stronger wind can increase heat gain.'):params.flow===0?T('血流關閉，核心不再經這條路把熱送到嘴巴；嘴巴仍與空氣交換熱。','Blood flow is off. The core no longer sends heat by this route, while the bill still exchanges heat with air.'):T('血流把核心熱送到嘴巴，溫差讓熱流向空氣。比較無風和有風，觀察交換速度。','Blood flow delivers core heat to the bill. Temperature difference drives heat to air. Compare still and moving air.')};
case'E01':return {metrics:[metric(T('儲存能量','Stored energy'),`${f(r.energy*1000,1)} mJ`,T('毫焦耳＝千分之一焦耳','mJ = thousandth of a joule')),metric(T('有用／損失','Useful / lost'),`${f(r.useful*1000,1)} / ${f(r.loss*1000,1)}`,T('單位 mJ，合計不超過輸入','mJ; total does not exceed input')),metric(T('彈簧峰值功率','Spring peak power'),`${f(r.peak,2)} W`,T(`直接驅動 ${f(r.directPeak,2)} W`,`Direct drive ${f(r.directPeak,2)} W`))],explain:r.energy===0?T('沒有蓄能，就沒有出拳。彈簧不會自己製造能量。','No charge, no strike. The spring creates no energy.'):T(`同樣有效能量，彈簧在約 ${f(r.time*1000,2)} ms 釋放，直接驅動示例用 500 ms，所以功率更集中；阻尼消耗 ${f(r.loss*1000,1)} mJ。`,`The same useful energy is released in about ${f(r.time*1000,2)} ms by the spring versus 500 ms by direct drive. Damping consumes ${f(r.loss*1000,1)} mJ.`)};
case'E05':return {metrics:[metric(T('強度：最高應力','Strength: peak stress'),`${f(r.strength,0)} MPa`,T('最高點，不是面積','Peak, not area')),metric(T('韌性：整段面積','Toughness: total area'),`${f(r.toughness,1)} MJ/m³`,T('每單位體積吸收能量','Energy per specimen volume')),metric(T('接球能量／容量','Ball energy / capacity'),`${f(r.ball,2)} / ${f(r.capacity,2)} J`,r.catches?T('理想模型容量足夠','Enough ideal capacity'):T('超過容量，斷裂','Capacity exceeded: failure'))],explain:done?T(r.catches?'這個示例材料的能量容量足夠接住小球；換硬脆材料，比較最高點和面積。':'小球能量超過材料容量，材料斷裂；高強度不保證容量大。',r.catches?'This sample has enough ideal energy capacity. Try the brittle material and compare its peak and area.':'The ball exceeds capacity and the sample fails. High strength does not guarantee high capacity.'):T(r.broken?'你已拉到這條曲線的斷裂點。換材料或重設，再比較斷裂前能吸收多少能量。':'拉長時，填色面積是已存入的能量；完整曲線面積代表理想斷裂容量。',r.broken?'You reached this curve’s failure strain. Change material or reset and compare energy before failure.':'While stretching, shaded area is energy stored so far. Total area represents ideal energy capacity.')};
case'F03':return {metrics:[metric(T('上游水位','Upstream level'),`${f(r.level,2)} m`,T(`蓄水 ${f(r.volume,1)} m³`,`Storage ${f(r.volume,1)} m³`)),metric(T('下游流量','Downstream flow'),`${f(r.out,2)} m³/s`,T(`溢流 ${f(r.overflow,2)} m³/s`,`Overflow ${f(r.overflow,2)} m³/s`)),metric(T('收支核對誤差','Ledger error'),`${f(Math.abs(r.balance),6)} m³`,T('初始＋流入－流出－庫存','Initial + in − out − stored'))],explain:r.overflow>.001?T('水面高過壩頂，水正從上面溢向下游；水壩不能無限蓄水。','The pond is above the crest: overflow sends water downstream. A dam cannot store unlimited water.'):params.rain===0?T('入流已停止；只要缺口有出水，庫存與水位就會下降。把缺口開大再比較。','Inflow is off. An open gap drains storage and lowers the level. Try widening the gap.'):T('庫存只會增加「流入減流出」的差額。縮小缺口能蓄水，也會改變下游供水。','Storage changes by inflow minus outflow. A smaller gap retains water and changes downstream supply.')};
case'H07':return {metrics:[metric(T('獨立相機日','Independent camera-days'),`${r.n}`,T('相機數 × 天數','Cameras × days')),metric(T('有動物卻沒拍到','Miss probability if present'),`${f(r.miss*100,2)}%`,T('理論機率，不是滅絕機率','Theory, not extinction probability')),metric(T('100 次中的漏拍','Misses in 100 surveys'),done?`${r.misses} / 100`:T('等待調查','Run survey'),T('固定種子可重做','Repeatable with fixed seed'))],explain:params.p===0?T('偵測率為零，再多相機也拍不到。增加次數無法修補完全不能偵測的設備。','At zero detection, more cameras still take no photos. More trials cannot fix a device that never detects.'):T('每座假想森林都有動物，仍可能沒有照片。理論機率和這 100 次模擬會有抽樣差異。','Every imaginary forest contains an animal, yet some have no photo. These 100 trials can differ from the theoretical probability.')};
case'A11':return {metrics:[metric(T('接觸峰值力','Peak contact force'),`${f(r.peak,0)} N`,T('整次測試的最大力','Maximum in the test')),metric(T('腳墊是否觸底','Bottoming out'),r.bottom?T('觸底','Yes'):T('沒有','No'),T('示例腳墊厚 8 cm','Example pad: 8 cm thick')),metric(T('接觸衝量','Contact impulse'),`${f(r.impulse,1)} N·s`,T('含 1.5 秒間的支撐重量','Includes weight support over 1.5 s'))],explain:r.bottom?T('腳墊太軟，壓縮超過 8 cm 後碰到硬底；看曲線的尖峰。適度緩衝比一味變軟更重要。','The pad is too soft and hits the hard stop beyond 8 cm. Look for a spike. Softer is not always better.'):T('腳墊變形讓減速歷時變長，阻尼消耗能量；試比較硬墊、適中墊和過軟墊。','Deformation spreads stopping over time and damping uses energy. Compare stiff, moderate and too-soft pads.')};
case'B07':return {metrics:[metric(T('捕到的食物','Captured food'),`${f(r.catchMass,2)} kg`,T('密度 × 吞水 × 80%','Density × gulp × 80%')),metric(T('收入／支出','Gain / cost'),`${f(r.gain/1000,2)} / ${f(r.cost/1000,2)}`,T('單位 MJ＝百萬焦耳','MJ = million joules')),metric(T('單次淨收益','Net per gulp'),`${f(r.net/1000,2)} MJ`,r.net>=0?T('收入超過支出','Gain exceeds cost'):T('支出超過收入','Cost exceeds gain'))],explain:r.net<0?T('這口花的比吃到的多！水裡食物太少，或吞水成本太高；再加大嘴巴不一定划算。','This gulp costs more than it gains. Food is sparse or costs are high. A bigger gulp may not help.'):T('這一口收入超過支出；把食物密度降低，找到淨收益變負的位置。','This gulp gains more than it costs. Lower density to find where net energy becomes negative.')};}}
function chart(series,xmax,ymax,xlabel,ylabel,x=365,y=105,w=300,h=160){let out=`${line(x,y+h,x+w,y+h,'#50687b')}${line(x,y,x,y+h,'#50687b')}${svgText(x,y-15,ylabel,'small')}${svgText(x+w/2-55,y+h+38,xlabel,'small')}`;for(let i=1;i<4;i++)out+=`<line class="grid" x1="${x}" y1="${y+h-i*h/4}" x2="${x+w}" y2="${y+h-i*h/4}"/>`;out+=svgText(x-5,y+h+20,'0','small')+svgText(x+w-30,y+h+20,f(xmax,Number.isInteger(xmax)?0:xmax<1?2:1),'small')+svgText(x-45,y+4,f(ymax,ymax<1?2:0),'small');series.forEach((s,i)=>{if(!s.length)return;const d=s.map((a,j)=>`${j?'L':'M'}${x+w*Math.min(a[0]/xmax,1)},${y+h-h*Math.min(a[1]/ymax,1)}`).join(' ');out+=`<path d="${d}" class="${i?'b':'a'}" ${i===2?'style="stroke:#ed9fba;stroke-dasharray:2 5"':''}/>`;});return out;}
const paw=(x,y,width=110,color='#bfcfdd',claws=false)=>`<g transform="translate(${x} ${y})"><path d="M${-width*.35},-110 Q${-width*.3},-50 ${-width*.5},-25 Q${-width*.62},10 0,14 Q${width*.63},12 ${width*.5},-25 Q${width*.26},-45 ${width*.28},-110" fill="${color}" stroke="#e5edeb" stroke-width="2"/><ellipse cy="-10" rx="${width*.32}" ry="15" fill="#65768a"/>${[-.3,-.1,.1,.3].map(a=>`<ellipse cx="${width*a}" cy="-31" rx="${width*.105}" ry="13" fill="#65768a"/>${claws?`<path d="M${width*a-4},-17 l8,${15+p.claw*.12} l-12,-4" fill="#fff0ce"/>`:''}`).join('')}</g>`;
function scene(r){let s=window.LabExtension?window.LabExtension.scene(C.id,r,p,{T,L,f,svgText,line,arrow,phase,running,done,C,gut,cropLayer,waterLayer,caviLayer,comparison:mode===1?comparison:null}):'';if(C.id==='F05'){const defs='<defs><marker id="gold" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#efb96c"/></marker></defs>';return `<div class="beetle-scenes"><div class="beetle-sky-panel"><svg class="scene beetle-sky" viewBox="30 40 290 300" role="img" aria-label="${e(T('天光線索示意','Sky-cue illustration'))}">${s.sky}</svg><p class="beetle-sky-caption">${p.cue?T('天光示意｜可見','Sky toy · visible'):T('天光示意｜遮住','Sky toy · covered')}</p></div><svg class="scene beetle-route" viewBox="370 40 300 300" role="img" aria-label="${e(L(C.title)+' · '+info(r).explain)}">${defs}${s.route}</svg></div>`;}switch(C.id){case'A01':{const ground=['#415c45','#68717b','#253e52'][p.ground],dx=r.slip&&running?Math.sin(phase*10)*14:0;s+=`<rect x="35" y="235" width="295" height="65" rx="14" fill="${ground}"/>${paw(174+dx,225,125,'#c9a673',true)}`;for(let i=0;i<10;i++)s+=line(40+i*30,260,53+i*30,246,'#789780');s+=arrow(180,181,-Math.min(p.push*.2,100),0,'#efb96c')+arrow(165,230,Math.min(r.force*.25,120),0);s+=svgText(43,75,T('一隻等效腳掌','Equivalent paw'),'title')+svgText(42,325,L(C.controls[0].options[p.ground])+(r.slip?T(' · 打滑',' · slipping'):T(' · 抓住',' · gripping')));s+=chart([Array.from({length:21},(_,i)=>[i/10,r.a*i/10])],2,30,T('時間 s','Time s'),T('速度 m/s','Speed m/s'));s+=svgText(410,70,T('假設持續推 2 秒','Assuming 2 s constant push'),'small');break;}
case'A09':{const yy=205+r.sink*50,width=Math.sqrt(p.area/400)*105;s+=`<path d="M35 214 Q100 204 170 214 T330 214 V302 H35Z" fill="#d7e8f5"/><path d="M35 251 H330 M35 278 H330" stroke="#a2bfd4" stroke-width="2"/>${paw(182,yy,width)}`;s+=svgText(43,70,T('同重量，換更大腳掌','Same weight, wider paws'),'title');s+=arrow(184,80,0,65,'#efb96c');s+=svgText(410,96,T('壓力越低，柱子越短','Lower pressure, shorter bar'));const h=Math.min(170,r.pressure*5);s+=`<rect x="448" y="${280-h}" width="68" height="${h}" rx="6" fill="#94dfe1"/>`;const ty=280-p.snow*5;s+=line(380,ty,636,ty,'#efb96c','7 4')+svgText(525,ty-10,T('雪的閾值','Snow threshold'),'small');s+=svgText(412,318,`${f(r.pressure,2)} kPa · ${p.area} cm²`);break;}
case'C01':{const end=130+p.distance/12*475,travel=r.time*40,progress=time/Math.max(.01,travel),x=progress<=.5?130+(end-130)*progress*2:end-(end-130)*(progress-.5)*2;s+=`<path d="M115 160 Q78 100 35 120 L55 156 L42 185 Q75 161 108 188 Q120 214 136 186 Q178 166 202 188 L187 156 L203 121 Q155 102 132 160Z" fill="#ab97d0" stroke="#d5c5ed" stroke-width="2"/><circle cx="119" cy="164" r="14" fill="#e6daef"/><path d="m106 154 2-18 9 16m9 0 9-16-1 20" fill="#e6daef"/><circle cx="115" cy="162" r="2" fill="#07101e"/><circle cx="126" cy="162" r="2" fill="#07101e"/>`;
if(running||done)s+=`<rect x="${end}" y="95" width="20" height="172" rx="8" fill="#efb96c"/>`;else s+=svgText(end-25,183,'?','title');s+=line(135,277,605,277,'#36566b');for(let i=0;i<=12;i+=3)s+=svgText(127+i/12*475,305,`${i} m`,'small');if(running)s+=`<circle cx="${Math.min(end,Math.max(130,x))}" cy="177" r="20" fill="none" stroke="${progress>.5?'#efb96c':'#94dfe1'}" stroke-width="4"/>`;s+=svgText(40,55,T('去程 → 障礙 → 回程','Out → obstacle → back'),'title')+svgText(315,82,T('動畫時間 ×40','Animation time ×40'),'small');if(done)s+=svgText(300,177,`${f(r.time*1000,1)} ms`,'title');break;}
case'D01':{const color=r.bill>35?'#ed9f74':r.bill>25?'#efb96c':'#86c9df';s+=`<ellipse cx="152" cy="210" rx="71" ry="82" fill="#142030" stroke="#6c8097" stroke-width="2"/><ellipse cx="173" cy="177" rx="44" ry="57" fill="#e5e1ce"/><circle cx="186" cy="126" r="46" fill="#132539"/><path d="M214 96 Q340 75 338 128 Q319 162 215 155 Z" fill="${color}" stroke="#f6ddbb" stroke-width="2"/><path d="M218 131 L329 130" stroke="#44536a" stroke-width="3"/><circle cx="190" cy="117" r="10" fill="#76c3db"/><circle cx="190" cy="117" r="4" fill="#07101e"/>${line(133,285,122,305,'#c5a77d')}${line(170,285,180,305,'#c5a77d')}`;s+=arrow(r.out>=0?270:345,190,r.out>=0?65:-65,0,r.out>=0?'#94dfe1':'#efb96c');s+=svgText(43,55,T('血流把熱送到喙','Blood carries heat to bill'),'title')+svgText(48,334,T('假色熱圖 · 示意','False colour · illustration'),'small');const hh=history.length?history:[[0,40,32],[time,r.core,r.bill]];s+=chart([hh.map(a=>[a[0],a[1]]),hh.map(a=>[a[0],a[2]])],Math.max(60,time),50,T('時間 s','Time s'),T('溫度 °C','Temperature °C'));s+=svgText(410,315,T('— 核心  ·  - - 喙','— Core  ·  - - Bill'),'small');break;}
case'E01':{const pts=r.points,index=Math.min(pts.length-1,Math.floor(phase*pts.length)),x=running&&pts.length?pts[index].x:p.x/1000;const armX=155+(p.x/1000-x)*4000;s+=`<ellipse cx="95" cy="237" rx="55" ry="36" fill="#437e88"/>${[0,1,2].map(i=>`<path d="m${60+i*20} 266 -10 20" stroke="#96d8d3" stroke-width="4"/>`).join('')}<circle cx="106" cy="196" r="11" fill="#efb96c"/><path d="M105 221 L150 191 L${armX} 159" stroke="#94dfe1" stroke-width="14" fill="none" stroke-linecap="round"/><circle cx="${armX}" cy="148" r="25" fill="#edac85"/><path d="M155 240 l10 -13 10 26 10 -26 10 26 10 -13" stroke="#efb96c" fill="none" stroke-width="4"/><rect x="278" y="134" width="27" height="140" rx="10" fill="#6a7889"/>`;s+=svgText(40,55,T('先蓄能，再開卡榫','Charge, then release latch'),'title')+svgText(43,315,T('槌臂示意 · 動畫放慢','Illustrative arm · slowed'),'small');const max=Math.max(.01,r.peak);s+=chart([pts.map(a=>[a.t*1000,a.power])],Math.max(1,r.time*1000),max,T('彈簧時間 ms','Spring time ms'),T('功率 W','Power W'),365,100,290,70);s+=chart([[[0,0],[250,r.directPeak],[500,0]]],500,Math.max(.001,r.directPeak),T('直接驅動時間 ms','Direct time ms'),T('功率 W','Power W'),365,235,290,60);s+=svgText(390,349,T('兩圖刻度不同，請比時間數字','Different scales: compare time numbers'),'small');break;}
case'E05':{const failed=done?!r.catches:r.broken,len=120*(1+Math.min(r.strain,.6));s+=svgText(40,55,T('同長度、同粗細試片','Same length & cross-section'),'title');s+=`<rect x="85" y="90" width="155" height="16" rx="7" fill="#71859b"/>`;if(failed)s+=`<path d="M163 106 v${len*.45} m-8 20 16-14 m-8 25 v${len*.4}" stroke="#ed9fba" stroke-width="4" fill="none"/>`;else s+=line(163,106,163,106+len);s+=`<circle cx="163" cy="${running?75+phase*(Math.min(303,130+len)-75):Math.min(303,130+len)}" r="${16+Math.sqrt(p.ball)*.35}" fill="#efb96c"/>`;s+=svgText(44,325,failed?T('試片已斷裂','Sample failed'):T('試片可以伸長','Sample extends'),'small');const mat=M.materials[p.mat],xm=.65,ym=1100;s+=chart(M.materials.map(x=>x.points),xm,ym,T('應變（伸長比例）','Strain (extension)'),T('應力 MPa','Stress MPa'));const points=mat.points.filter(a=>a[0]<=r.strain);if(!r.broken)points.push([r.strain,r.stress]);s+=`<path d="M365 265 ${points.map(a=>`L${365+300*a[0]/xm} ${265-160*a[1]/ym}`).join(' ')} L${365+300*Math.min(r.strain,mat.points.at(-1)[0])/xm} 265Z" fill="#94dfe144"/>`;s+=svgText(395,320,L(mat.name),'small');break;}
case'F03':{const level=Math.min(r.level,3),y=287-level*65,crest=287-p.height*65;s+=svgText(40,50,T('流入 − 流出 = 庫存變化','In − out = storage change'),'title');s+=`<path d="M40 290 H350 L400 307 H680" stroke="#72856f" stroke-width="12" fill="none"/><rect x="40" y="${y}" width="315" height="${287-y}" fill="#568dba99"/><rect x="378" y="280" width="300" height="22" fill="#568dba66"/><rect x="346" y="${crest}" width="35" height="${287-crest}" fill="#8c6d52" stroke="#d4b78a" stroke-width="2"/><rect x="344" y="${271-p.gap*.12}" width="40" height="${2+p.gap*.12}" fill="#94dfe1"/>`;s+=arrow(65,115,Math.min(100,p.rain*5),0)+arrow(418,267,Math.min(120,r.out*60),0);if(r.overflow>.001)s+=`<path d="M328 ${y} Q372 ${y-5} 396 279" stroke="#94dfe1" stroke-width="8" fill="none"/>`;s+=svgText(70,y-14,`${f(r.level,2)} m`,'title')+svgText(435,146,T('下游也需要水','Downstream needs water'))+svgText(418,190,`${f(r.out,2)} m³/s`,'title');s+=svgText(40,330,T(`初始 100 + 流入 ${f(r.inside,1)} − 流出 ${f(r.outside,1)} = ${f(r.volume,1)} m³`,`Initial 100 + in ${f(r.inside,1)} − out ${f(r.outside,1)} = ${f(r.volume,1)} m³`),'small');break;}
case'H07':{s+=svgText(40,50,T('100 座假想森林，都有動物','100 imaginary forests, all occupied'),'title');for(let i=0;i<100;i++){let x=40+(i%20)*32,y=100+Math.floor(i/20)*37;const hit=done&&r.trials[i];s+=`<rect x="${x}" y="${y}" width="25" height="27" rx="5" fill="${done?(hit?'#94dfe1':'#314558'):'#172d40'}" stroke="#587082"/>${done?svgText(x+6,y+20,hit?'●':'×'):''}`;}s+=svgText(40,315,T('● 拍到   × 有動物卻沒拍到','● Detected   × Present but missed'));s+=svgText(42,344,T(`固定種子 ${p.seed} · 每台每天視為獨立一次`,`Seed ${p.seed} · one independent trial per camera-day`),'small');break;}
case'A11':{const i=Math.min(r.points.length-1,Math.floor(phase*r.points.length)),y=running||done?r.points[Math.max(0,i)].y:-p.height/100;const py=205+Math.min(.1,y)*500;const padH=Math.max(4,40-Math.max(0,y)*500);s+=svgText(40,55,T('10 kg 示例重物，不是整隻象','10 kg test mass, not an elephant'),'title');s+=`<rect x="86" y="249" width="210" height="20" rx="5" fill="#65798d"/><rect x="100" y="${249-padH}" width="182" height="${padH}" rx="12" fill="#a799c7" stroke="#d5c5e9" stroke-width="2"/><path d="M131 107 H240 L259 ${py} Q180 ${py+22} 114 ${py}Z" fill="#879dad" stroke="#c8d9e6" stroke-width="2"/>`;s+=svgText(48,315,r.bottom?T('硬底會產生額外尖峰','Hard stop adds a force spike'):T('脂肪與纖維組織的啟發','Inspired by fat & fibrous tissue'),'small');s+=chart([r.points.map(a=>[a.t,a.force])],1.5,Math.max(500,r.peak*1.1),T('時間 s','Time s'),T('接觸力 N','Contact force N'));break;}
case'B07':{s+=svgText(40,50,T('吃到的能量 − 吞水成本','Food energy − gulp cost'),'title');s+=`<path d="M40 177 Q111 107 266 134 Q295 147 321 168 L362 146 L355 184 L368 217 L316 198 Q171 255 66 215 Z" fill="#4b8da1" stroke="#a3d6dc" stroke-width="2"/><path d="M190 191 Q248 236 303 186" stroke="#d5e6e6" fill="#122a3f" stroke-width="3"/><circle cx="270" cy="159" r="4" fill="#091827"/>`;const rand=M.rng(31);for(let i=0;i<Math.min(100,Math.ceil(p.density*500));i++){let x=55+rand()*285,y=105+rand()*170;if(running){x+=(270-x)*phase;y+=(184-y)*phase;}s+=`<path d="m${x} ${y} 5 2 -4 4" fill="none" stroke="#efb96c" stroke-width="2"/>`;}const ymax=Math.max(r.gain,r.cost,1);s+=svgText(405,99,T('單口能量帳（MJ）','Single-gulp ledger (MJ)'),'small');[['#94dfe1',r.gain,T('收入','Gain')],['#efb96c',r.cost,T('支出','Cost')]].forEach((a,i)=>{const h=155*a[1]/ymax,x=435+i*115;s+=`<rect x="${x}" y="${272-h}" width="65" height="${h}" rx="6" fill="${a[0]}"/>${svgText(x,298,a[2])}${svgText(x,Math.max(108,260-h),f(a[1]/1000,1),'small')}`;});s+=svgText(45,322,T('鯨鬚濾食 · 粒子非真實蝦數','Baleen filtration · symbolic krill'),'small');break;}}
return `<svg class="scene" viewBox="${C.id==='G07'?'0 70 720 210':'0 0 720 360'}" role="img" aria-label="${e(L(C.title)+' · '+info(r).explain)}"><defs><marker id="cyan" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#94dfe1"/></marker><marker id="gold" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#efb96c"/></marker></defs>${s}</svg>`;}
function controls(list=C.controls){return list.map(c=>{const label=L(c.label);return `<div class="control"><div class="control-top"><label for="${c.options?'choice-':'range-'}${c.key}">${e(label)}</label>${!c.options?`<input class="number" id="num-${c.key}" type="number" min="${c.min}" max="${c.max}" step="${c.step}" value="${p[c.key]}" aria-label="${e(label+' '+T('數值','number'))}"><span class="unit">${e(unit(c))}</span>`:''}</div>${c.options?`<div class="choices" id="choice-${c.key}" role="group" aria-label="${e(label)}">${c.options.map((o,i)=>`<button data-choice="${c.key}" data-value="${i}" aria-pressed="${p[c.key]===i&&!(C.id==='D05'&&c.key==='layout'&&p.positions)}">${e(L(o))}</button>`).join('')}</div>`:`<input type="range" id="range-${c.key}" data-key="${c.key}" min="${c.min}" max="${c.max}" step="${c.step}" value="${p[c.key]}" aria-label="${e(label)}">`}</div>`;}).join('');}
function build(){const monarchFocus=C.id==='G07'?document.activeElement?.id:null;if(['A06','A07','A08','A10'].includes(C.id)&&$('.podcast img'))a06CoverNode=$('.podcast img');document.documentElement.lang=lang?'en':'zh-Hant';document.title=L(C.title)+'｜'+T('科學好好聽','Science Good Listen');const cp=C.podcast;$('#app').innerHTML=`<header class="topbar"><a class="brand" href="https://gongo.app/" target="_blank" rel="noopener"><img class="logo" src="logo.png" alt="${T('科學好好聽','Science Good Listen')}"><span>${T('動物機制實驗室','Animal science lab')}</span></a><nav class="switch" aria-label="${T('探索模式','Lab mode')}"><button id="explore" aria-pressed="${mode===0}">${T('探索','Explore')}</button><button id="compare" aria-pressed="${mode===1}">${T('對照','Compare')}</button></nav><div class="switch" role="group" aria-label="${T('語言','Language')}"><button id="zh" aria-pressed="${lang===0}">中文</button><button id="en" aria-pressed="${lang===1}">EN</button></div></header><section class="heading"><span class="eyebrow">${C.id} · ${T('科學好好聽 · 動手發現','SCIENCE GOOD LISTEN · DISCOVER')}</span><h1>${e(L(C.title))}</h1><p class="question">${e(L(C.question))}</p></section><main><div class="lab"><section class="view" aria-label="${e(T('觀察畫面','Observation'))}"><div class="scene-header"><strong>${T('教學模型 · 假設值','Teaching model · assumed values')}</strong><span id="clock"></span></div>${C.id==='G07'?'<div id="monarch-station-names" class="monarch-row"></div>':''}<div id="scene"></div>${C.id==='G07'?'<div id="monarch-resources" class="monarch-row"></div><p id="monarch-summary" aria-live="polite"></p>':''}<p class="scene-note">${C.id==='B12'?T('功率越大，推水每秒花能量越多；圖形為示意。','Higher power = more energy each second. Schematic.'):T('圖形為機制示意，形狀與移動不代表真實比例。','Mechanism diagram; shapes and motion are not to scale.')}</p><div class="actions ${C.audio?'audioactions':''}"><button id="run" class="primary"></button><button id="step">${T('逐步','Step')}</button><button id="reset">${T('重設','Reset')}</button>${C.id==='C01'?`<button id="mute" aria-label="${T('切換可聽替代音，預設靜音','Toggle audible substitute tone; muted by default')}" aria-pressed="${muted}">${muted?T('靜音','Muted'):T('有聲','Tone')}</button>`:''}${C.audio?`<button id="listen-cue" aria-pressed="${!muted}" aria-label="${T('試聽或停止小音量合成音，不是動物錄音','Preview or stop a quiet synthetic cue, not an animal recording')}">${muted?T('試聽合成音',C.id==='C08'?'Model sound':'Synthetic cue'):T('停止聲音','Stop sound')}</button>`:''}</div></section><section class="controls ${['B05','B06','B08','B09','B10','B11','B12','C02','C03','C04','C05','C06','C07','C08','C09','C10','C11','C12','D02','D03','D05','D07','D08','D09','D10','D11','D12','E02','F05'].includes(C.id)?'compact':''}"><h2>${T('動手試試','Try it')}</h2><p class="hint">${e(L(C.hint))}</p>${C.id==='D10'?controls(C.controls.slice(0,2))+gutTools()+controls(C.controls.slice(2)):(C.id==='D09'?leafTools():'')+controls()+(C.id==='D11'?cropTools():C.id==='D12'?waterTools():C.id==='E02'?caviTools():'')}${C.id==='D05'?`<div class="huddle-move"><p>${T('移動粉框企鵝；成功後從0重看','Move the marked bird; success restarts at 0')}</p><div class="huddle-arrows">${['→','↗','↖','←','↙','↘'].map((v,i)=>`<button data-huddle-move="${i}" aria-label="${T('移動企鵝：','Move bird: ')+v}">${v}</button>`).join('')}</div><p id="huddle-status" aria-live="polite"></p></div>`:''}</section></div><section class="results" aria-label="${T('實驗結果','Results')}"><div class="metrics" id="metrics"></div><p class="explain" id="explain"></p><section id="comparison" class="card" ${mode===0?'hidden':''}><h2>${T('一次只改一個條件','Change one condition at a time')}</h2><p>${C.id==='F09'?T('魚／海葵單獨對照保留目前掠食、養分與擁擠，只改搭配。養分示範兩組都用一起、養分7／0，保留目前掠食與擁擠。各方基準、損失、成本與結餘分開；四格圖都是即時假設結果，沒有播放時間。','Fish/host-alone comparisons retain current pressure, nutrients and crowding, changing only pairing. The nutrient demo sets Together in both groups and nutrients 7/0, retaining pressure/crowding. Each baseline, loss, cost and net is separate. Four tiles show live hypothetical results, without playback time.'):C.id==='F05'?T('兩組都走完整80步，從相同朝向0°開始，使用同一種子逐步配對擾動；只改按鈕標出的條件。重播只改主畫面，保存卡始終列完整結果。誤差相對所列參考方向；遮住時仍可由人核對，但蟲看不到它。','Both complete 80 steps from the same 0° heading with matched per-step random draws; only the named condition changes. Replay changes the main view, while cards retain full endpoints. Error uses the listed reference direction: a human can check it when covered, but the beetle cannot see it.'):C.id==='C12'?T('保存卡保留各組完整100公尺結局；無方向組停0公尺。重播只改主地圖的觀察進度，卡片不變。不把不同實際路程／時刻當相同終點，一致性也不是成功率。','Cards retain each complete 100 m example endpoint; undefined groups stay at 0 m. Replay changes only the main map’s progress. Different actual distances/times are not matched endpoints, and agreement is not success probability.'):C.id==='C11'?T('兩組都看相同2秒觀察時刻，完整參考曲線只供核對。下方格圖各按自己的取樣與人工疊圖設定顯示；最近取樣時刻可以不同。小眼數不會補拍兩張之間。','Both show the same observation time, up to 2 s; the full reference curve is only a guide. Each grid uses its own sampling and artificial blending settings, so last sample times may differ. More cells do not capture between frames.'):C.id==='C10'?T('保存卡列各區的時間平均透光強度，不隨電場箭頭改變。兩區入射強度各自相同，不是把同一束光重複算兩次；圓偏振兩區相同。只改標出的條件。','Cards retain each patch’s time-averaged transmission, independent of the field arrow. Each patch has the same input intensity; one beam is not counted twice. Both circular patches match. Only the named setting changes.'):C.id==='C09'?T('兩組都在列出的喙尖位置即時取樣，只改標出的條件。震動與嗅覺分開，不合成找蟲分數；揭開只供人核對位置，保留數據與對照，沒有播放時刻。','Both groups sample live at the listed bill-tip positions; only the named condition changes. Vibration and smell stay separate, without a combined localization score. Reveal is a human check that retains data and comparisons, with no playback time.'):C.id==='C08'?T('保存卡列各組的波形振動頻率、包絡衰減與敲擊輸入能量，不隨黃線前進改寫。換木段會套用一組示例參數，質量也可能不同；同衝量不一定同能量。頻譜按各自峰值正規化，不比較響度。','Cards retain each group’s waveform frequency, envelope decay and tap input energy, independent of cursor progress. Changing a sample applies its illustrative parameter set, including possibly different mass: equal impulse need not mean equal energy. Spectra use their own peaks for normalization, not loudness.'):C.id==='C07'?T('各組以列出的表面溫度即時計算，只改標出的條件；沒有播放時刻。關燈只改可見圖，熱資料相同；障壁改為背景同溫表面的放射。','Each group uses its listed surface temperatures live; only the named condition changes, with no playback time. Lights affect only the visible image; an IR-opaque barrier replaces the mouse contribution with background-temperature emission.'):C.id==='C05'?T('各組用相同鼻部四點即時取樣，只改標出的條件；沒有播放時間。反轉示範用0噪音；加噪音後不保證讀數全部反號，箭頭也不是來源指針。','Both groups sample the same four snout points live; only the named condition changes, with no playback time. Reversal uses zero noise. Noisy readings need not all reverse, and the arrow is not a source pointer.'):C.id==='C04'?T('各組在所列位置即時取樣，只改示範標出的條件；沒有播放時間。近／遠示範沿固定方向，跨方向不保證距離越遠電差越小。','Each group samples its listed position live; only the named condition changes, with no playback time. The near/far demo fixes direction; distance alone does not order voltages across directions.'):C.id==='B10'?T('每組保存完整六點擊與各自整段時長；速率不同時，結束時刻也不同。重播不改保存卡；切比較方式會按同一種分析重算兩卡，不翻譯意思。','Each card retains all six clicks and its own full duration. Speeds can give different end times. Replay keeps the cards; changing analysis recalculates both alike, without translating meaning.'):C.id==='B09'?T('每組列完整接收點預估與各自單程旅行秒數。2秒動畫只示意傳播；接收級不隨動畫逐步累加，不推斷是否聽懂。','Each group shows a full receiver prediction and its own one-way seconds. The 2 s diagram illustrates propagation; levels do not accumulate with animation or infer understanding.'):C.id==='B08'?T('兩組各自計算到返程完成或首次耗盡，完整結局保存在卡片。每組明示停止時刻；不同時刻的儲量不能當成同時比較。','Each ledger runs to the completed ascent or first depletion. Cards retain full endpoints and explicit stopping times; stores at different times are not simultaneous.'):C.id==='B04'?T('兩組各看最多1模型秒，碰資料邊界各自停住。每組明示實際推算時刻；停止推算不是找到平衡，結局可能不是相同時刻。','Each group runs for up to 1 model second and halts at its own data boundary. Each prediction time is explicit; a data stop is not equilibrium, and endpoints may have different times.'):C.id==='B06'?T('兩組用各自設定的等待，加同一段觀察進度。尾流年齡是等待加已觀察秒數；等進度不一定等年齡。','Each group uses its chosen wait plus matched observation progress. Wake age is wait plus elapsed model seconds; matched progress need not mean equal age.'):C.id==='D03'?T('每個條件各含兔A（200cm²）與兔B（可調耳面積）。條件A／B只改按鈕標出的項目；都是即時穩定比較，不是飛行或播放時刻。','Each condition contains rabbit A (200cm²) and rabbit B (adjustable ear area). Conditions A/B change only the named setting: live steady comparisons, with no playback time.'):C.id==='C06'?T('兩組都從相同位置與朝向出發，最多60步；失去線索或到達高濃度時可能在不同步提前停，步數與原因分別列出，不代表相同時刻的終點比較。保存卡保留各自完整結局，重播不會改成途中數字。','Both start at the same position and heading, with at most 60 steps. Lost cues or high concentration may stop them at different steps; each count and reason is explicit, so endpoints are not simultaneous. Saved cards retain each full endpoint during replay.'):C.id==='B11'?T('兩組從相同60點開始，各看10分鐘或首次耗盡。各組明示停止時刻；不同時間的累計量不能當成同時比較。','Both start with 60 units and run to ten minutes or first depletion. Stop times are explicit; totals at different times are not simultaneous.'):C.id==='E09'?T('兩組只改標出的條件，保留所列完整幾何結果；即時比較，沒有播放時刻。向內缺口未計算，不拿0當完全覆蓋。','Only the named condition changes; cards retain complete listed geometry. Live comparison has no playback time. Inward gaps are not calculated; zero is not coverage proof.'):C.id==='E02'?T('兩組只改標出的條件；各看同一概念階段，不是真實時間或相同能量的力比較。','Only the named setting changes. Both show a matched concept phase, not real time or a force comparison at equal energy.'):C.id==='D12'?T('兩組完整24小時、相同6小時活動；只改標出的條件。保存卡列全天收入、流失與淨變化，重播不改卡；淨差額不是各時段所需初始存水。','Both cover24 hours and6 active hours; only the named condition changes. Cards retain full-day input,loss and net change during replay. Net change is not the initial store required at each time.'):C.id==='D11'?T('各組只改標出的囊格或纖維份。空間各為100格，保存卡列各組完整纖維投入、利用與留下；2秒金點只示意投入移動，重播不改保存值，不是真消化時間。','Only the named pouch cells or fiber units change. Each has100space cells; cards retain each full fiber input,used and left. The2s gold marker only illustrates input moving; replay keeps saved values and is not digestion time.'):C.id==='D10'?T('各組只改標出的條件；數值是完整投入的去向，不受2秒分流動畫影響。碳、氮與水分開核對。','Only the named condition changes. Values cover the full input, independent of the2s routing animation. Carbon, nitrogen and water have separate ledgers.'):C.id==='D09'?T('三組示範每次只改標出的份數或飲水；數值是完整餐盤，不隨分流動畫改變。水和處理點另帳，不能混當健康分數。','Each demo changes only the named portion count or drinking water. Values are for the whole meal, independent of flow animation. Water and load stay separate, not a health score.'):C.id==='D08'?T('兩組都算完整24小時；只改標出的主動安排或食物條件，休息補足剩餘時間（休息不等於睡眠）。保存卡保留全天帳，不隨重播變成部分時段。','Both cover24 hours. Only the named active-time or food setting changes; remaining time becomes rest, not necessarily sleep. Saved cards retain the full-day ledger during replay.'):C.id==='D07'?T('同一個60日計畫，B只改標出的條件。各組列實際停止日；不足者不假算完成。','Same60-day plan; B changes only the named condition. Each ledger gives its actual stopping day; underfunded entries stay unpaid.') : T('點示範會建立 A／B 兩組相同起點。A 是原條件，B 只改變標出的項目；各圖標示同一觀察時刻或階段。','A demo creates matched starting conditions. A is the baseline; B changes only the named variable. Each diagram labels its matched time or stage.')}</p><div class="comparisons">${C.comparisons.map((x,i)=>`<button data-demo="${i}">${e(L(x.label))}</button>`).join('')}</div><div id="saved" class="saved"></div></section></section><div class="below"><section class="card"><span class="eyebrow">01 ${T('先猜','PREDICT')} → 02 ${T('調整','CHANGE')} → 03 ${T('解釋','EXPLAIN')}</span><h2 style="margin-top:8px">${e(L(C.mission))}</h2><div class="challenge">${C.options.map((x,i)=>`<button data-answer="${i}" class="${selected===i?'selected':''}" aria-pressed="${selected===i}">${e(L(x))}</button>`).join('')}</div><p id="feedback" class="feedback">${feedback?e(feedback):T('隨時能操作。先猜，再用模型檢查想法。','Controls are always ready. Predict, then check your idea with the model.')}</p><p>${e(L(C.reason))}</p><div class="podcast"><img class="${cp.verified&&cp.coverAvailable!==false?'episode-cover':'logo-fallback'}" src="${cp.verified&&cp.coverAvailable!==false?(cp.coverFormat==='webp'?'cover.webp':'cover.jpg'):'logo.png'}" alt="${cp.verified&&cp.coverAvailable!==false?T('官方單集封面','Official episode cover'):T('科學好好聽 Logo','Science Good Listen logo')}"><div><h3>${e(C.episodeTitle)}</h3><a href="${e(cp.url)}" target="_blank" rel="noopener">${cp.verified?T('聽這集 ↗','Listen to this episode ↗'):T('前往節目 ↗','Open the podcast ↗')}</a><p>${cp.verified?e(lang?(cp.durationEn||cp.duration.replace(' 分 ', ' min ').replace(' 秒',' sec')):cp.duration)+(cp.subscribersOnly?T(' · 訂閱者限定',' · Subscribers only'):''):T('主題素材集數 '+C.ep+'；單集收聽連結尚待官方確認。','Topic source '+C.ep+'; the episode listening link awaits official confirmation.')}</p>${cp.verified&&cp.coverAvailable===false?'<p>'+T('官方封面待取得，先顯示節目Logo。','Official cover pending; the podcast logo is shown.')+'</p>':''}</div></div></section><section class="card"><details class="source"><summary>${T('來源、假設與模型限制','Sources, assumptions & limits')}</summary><p>${e(L(C.limit))}</p><ul><li><a href="${e(C.source[0])}" target="_blank" rel="noopener">${e(['F09','G07'].includes(C.id)&&lang?(C.source[2]||C.source[1]):C.source[1])}</a></li>${(C.extraSources||[]).map(s=>'<li><a href="'+e(s[0])+'" target="_blank" rel="noopener">'+e(['F09','G07'].includes(C.id)&&lang?(s[2]||s[1]):s[1])+'</a></li>').join('')}<li>${T('節目主題素材：','Podcast topic source: ')}${e(C.episodeTitle)}</li><li>${T('原創 SVG、程序與合成資料：科學好好聽，2026-10-03。外部媒體僅用於可選收聽，核心不需要網路。','Original SVG, code & synthetic data: Science Good Listen, 2026-10-03. External media is optional; the core works without a network.')}</li></ul><p>${C.id==='C06'?T('左右取樣是教學概念；研究對蛇是否用邊界偵測有不同結果。本站不重現神經反應。','Bilateral sampling is a teaching concept; studies differ on snake edge detection. This is not a neural model.'):T('研究支持機制方向；示例參數未與真實動物量測校準。','Research supports the mechanism; example parameters are not calibrated to animal measurements.')}</p></details><details class="source"><summary>${T('揭開進階公式','Reveal the formulas')}</summary><pre class="formula">${e(lang?C.formula:(C.formulaZh||C.formula))}</pre></details><p>${C.id==='G07'?T('鍵盤：Tab 選擇按鈕，Enter或空白鍵套用；所有控制隨時可用。','Keyboard: Tab to a button; Enter or Space applies it. All controls are ready.'):['D02','D03','D05','D09','D10','D11','D12','E02','E09'].includes(C.id)?T('鍵盤：Tab 選控制、方向鍵調滑桿；輸入數值後按 Enter 套用。所有任務都能靜音完成。','Keyboard: Tab to controls, arrows for sliders; press Enter to apply a typed number. All tasks work without sound.'):T('鍵盤：Tab 選控制、方向鍵調滑桿；也能直接輸入數值。靜音仍能完成所有任務。','Keyboard: Tab to controls, arrow keys for sliders, or type numbers. All tasks work without sound.')}</p><p>${C.id==='G07'?T('靜態資源核對，沒有播放或時間進度。改資源不代表立即死亡；重設才還原全部示例。','Static resource matching, without playback or elapsed time. Removing a resource does not imply instant death; Reset restores the example.'):C.id==='F05'?T('逐步前進10步並暫停；80步後停留終點，按再走一次重播。改設定由起點重看；同值、語言、模式與猜題保留進度。每步1個教具距離單位，2秒播放不是真蟲速度。','Step advances 10 steps and pauses. At 80 steps retain the endpoint; use Walk again to replay. A changed setting restarts at the origin; same values, language, mode and predictions keep progress. Each step is one toy distance unit; 2 s of playback is not real beetle speed.'):C.id==='C12'?T('逐步5公尺；完成後可從頭逐步。改線索重開路程，同值／語言／模式保留；保存卡始終是各組完整結局。','Step advances 5 m and restarts after completion. Cue changes restart the route; same values/language/mode retain progress. Cards always retain full endpoints.'):C.id==='C11'?T('播放慢4倍看2模型秒；逐步看62.5毫秒，不一定拍到新張。小眼／取樣率／人工疊圖保留進度並重取樣參考資料；物體頻率／寬度改變才重開。','Playback shows 2 model seconds at 4× slow. Step advances 62.5 ms and need not capture a frame. Cells/rate/blending retain progress and resample the reference; object frequency/width changes restart.'):C.id==='C10'?T('轉分析片立即改平均透光強度。播放只看圖案區入射電場的概念循環，不是真實光頻率；逐步看¼圈。','Rotate the analyzer to change mean transmission. Playback shows conceptual input-field cycles for the pattern patch, not optical frequency; Step advances ¼ cycle.'):C.id==='C09'?T('移動喙尖立即更新讀數；揭開只是核對位置。曲線預覽100ms，沒有自動找蟲或播放時刻。','Moving the tip updates readings immediately. Reveal is a position check. Curves preview100ms, with no automatic localization or playback time.'):C.id==='C07'?T('所有溫度與開關立即更新；右圖用固定灰階，不會自動加強對比。所有任務都能靜音完成。','Temperatures and switches update immediately. The fixed grayscale never boosts contrast automatically. All tasks work without sound.'):C.id==='C05'?T('方向、位置、電流和噪音立即更新讀數；揭曉只供核對，保留數據與對照。','Angle, position, current and noise update readings immediately. Reveal is a visual check and retains data and comparisons.'):C.id==='C04'?T('位置和開關立即更新兩條線索；揭曉只供核對，不改數值。','Position and switches update both cues immediately. Reveal is a visual check and never changes readings.'):T('控制隨時可用。動態示範預設暫停；有逐步按鈕的實驗可慢慢看。','Controls are always ready. Motion demonstrations start paused; labs with a step button can be inspected slowly.')}</p></section></div></main><footer><a href="../batch01/">${T('回到動物機制實驗室','Animal science labs')}</a> · ${T('科學好好聽','Science Good Listen')} · ${C.id} · ${T('模型版本','Model version')} ${e(C.date||'2026-10-03')}</footer>`;
if(['A06','A07','A08','A10'].includes(C.id)&&a06CoverNode){a06CoverNode.alt=T('官方單集封面','Official episode cover');$('.podcast img').replaceWith(a06CoverNode);}if(['E09','F09','G01','G07','A08','A10','C04','C05','C07','C09','D03'].includes(C.id)){$('#run').remove();$('#step').remove();}$('#zh').onclick=()=>changeLang(0);$('#en').onclick=()=>changeLang(1);$('#explore').onclick=()=>changeMode(0);$('#compare').onclick=()=>changeMode(1);if($('#run'))$('#run').onclick=run;if($('#step'))$('#step').onclick=step;if($('#reset'))$('#reset').onclick=reset;if(C.id==='D05')document.querySelectorAll('[data-huddle-move]').forEach(b=>b.onclick=()=>huddleMove(Number(b.dataset.huddleMove)));if($('#mute'))$('#mute').onclick=()=>{muted=!muted;build();};
document.querySelectorAll('[data-key]').forEach(x=>x.oninput=()=>setParam(x.dataset.key,x.value));C.controls.filter(c=>!c.options).forEach(c=>{const n=$('#num-'+c.key);n.onchange=()=>setParam(c.key,n.value);n.onkeydown=ev=>{if(ev.key==='Enter'){ev.preventDefault();setParam(c.key,n.value);}};});document.querySelectorAll('[data-choice]').forEach(x=>x.onclick=()=>{if(p[x.dataset.choice]===Number(x.dataset.value)&&!(C.id==='D05'&&x.dataset.choice==='layout'&&p.positions))return;setParam(x.dataset.choice,x.dataset.value);});document.querySelectorAll('[data-answer]').forEach(x=>x.onclick=()=>{selected=Number(x.dataset.answer);feedback=selected===C.answer?T('你的預測符合模型！試用對照模式驗證。','Your prediction matches the model. Test it in Compare.'):T('試著調整條件，再看結果能不能支持你的猜測。','Change conditions and check whether results support your guess.');rebuildTurnDetails();});document.querySelectorAll('[data-demo]').forEach(x=>x.onclick=()=>demo(Number(x.dataset.demo)));if($('#listen-cue'))$('#listen-cue').onclick=previewSound;if(C.id==='D12')document.querySelectorAll('[data-water-layer]').forEach(x=>x.onclick=()=>{waterLayer=Number(x.dataset.waterLayer);document.querySelectorAll('[data-water-layer]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.waterLayer)===waterLayer)));$('#water-note').textContent=L(waterNotes[waterLayer+1]);update();});if(C.id==='E02')document.querySelectorAll('[data-cavi-layer]').forEach(x=>x.onclick=()=>{caviLayer=Number(x.dataset.caviLayer);document.querySelectorAll('[data-cavi-layer]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.caviLayer)===caviLayer)));$('#cavi-note').textContent=L(caviNotes[caviLayer+1]);update();});if(C.id==='G07')$('.controls').append($('.actions'));update();if(monarchFocus)$('#'+monarchFocus)?.focus({preventScroll:true});bindProbe();if(C.id==='D09')bindLeaves();if(C.id==='D11')document.querySelectorAll('[data-crop-layer]').forEach(b=>b.onclick=()=>{cropLayer=Number(b.dataset.cropLayer);document.querySelectorAll('[data-crop-layer]').forEach(x=>x.setAttribute('aria-pressed',String(Number(x.dataset.cropLayer)===cropLayer)));$('#crop-note').textContent=L(cropNotes[cropLayer+1]);update();});if(C.id==='D10')document.querySelectorAll('[data-gut]').forEach(b=>b.onclick=()=>{gut=Number(b.dataset.gut);document.querySelectorAll('[data-gut]').forEach(x=>x.setAttribute('aria-pressed',String(Number(x.dataset.gut)===gut)));$('#gut-note').textContent=L(gutNotes[gut]);update();});}
const cropNames=[['全部','All'],['囊區','Pouch'],['肌肉區','Muscle'],['其他','Other']],cropNotes=[['橙色囊、粉色肌肉示例、灰色其他：總共100格。','Orange pouch, pink muscle toy, gray other: 100 cells total.'],['前腸囊區含嗉囊與後段食道；微生物在此發酵。','Foregut pouch: crop and rear esophagus; microbes ferment here.'],['粉色只示例可分配的肌肉空間；不換算速度。','Pink is only example allocatable muscle space; no speed calculation.'],['灰色固定25格是教具假設，不是真鳥器官比例。','Fixed 25 gray cells are a toy assumption, not real organ fractions.']];
const waterNames=[['全部','All'],['收入','Input'],['流失','Loss'],['體內差額','Body change']],waterNotes=[['每路寬度＝6px/mL；全24h結果。亮框只標教具時格。','Each width=6px/mL; full24h results. The frame marks only a toy time slot.'],['食物原有水與營養氧化產水不同；氧化還需要氧。','Water already in food differs from nutrient-oxidation water; oxidation also needs oxygen.'],['呼吸／其他蒸發分列；濃縮只減少排同量廢物的尿水。','Breathing and other evaporation are separate; concentration reduces water for the same waste.'],['收入−流失＝體內變化；缺口需原有水補，不是負庫存。','Input−loss=body-water change; a gap needs existing water, not negative inventory.']];
function waterTools(){return '<div class="crop-tools"><p>'+T('點一層看水路；保留實驗設定','Inspect a route; keep experiment settings')+'</p><div class="crop-buttons">'+waterNames.map((q,j)=>'<button data-water-layer="'+(j-1)+'" aria-pressed="'+(waterLayer===j-1)+'">'+e(L(q))+'</button>').join('')+'</div><p id="water-note" aria-live="polite">'+e(L(waterNotes[waterLayer+1]))+'</p></div>';}
function cropTools(){return '<div class="crop-tools"><p>'+T('點一層看提示；保留實驗設定','Inspect a layer; keep experiment settings')+'</p><div class="crop-buttons">'+cropNames.map((q,j)=>'<button data-crop-layer="'+(j-1)+'" aria-pressed="'+(cropLayer===j-1)+'">'+e(L(q))+'</button>').join('')+'</div><p id="crop-note" aria-live="polite">'+e(L(cropNotes[cropLayer+1]))+'</p></div>';}
const gutNames=[['瘤胃','Rumen'],['網胃','Reticulum'],['瓣胃','Omasum'],['皺胃','Abomasum']],gutNotes=[['瘤胃：微生物製成VFA（短鏈脂肪酸），牛可用來供能。從胃壁吸收。','Rumen: microbes make VFA (short-chain fatty acids) for energy. Uptake is through its wall.'],['網胃：與瘤胃互通；粗粒回嘴再嚼，小粒向後走。','Reticulum: exchanges with rumen; cud returns to the mouth.'],['瓣胃：多層皺摺；吸收部分水，食物繼續向後。','Omasum: folds absorb some water; digesta continues.'],['皺胃：酸和酶消化；微生物蛋白再到小腸吸收。','Abomasum: acid and enzymes; protein uptake continues in the intestine.']];
function gutTools(){return '<div class="gut-tools"><p>'+T('點一個隔間，看它做什麼；實驗保持原設定','Tap a room to inspect its job; experiment settings stay')+'</p><div class="gut-buttons">'+gutNames.map((q,j)=>'<button data-gut="'+j+'" aria-pressed="'+(gut===j)+'">'+e(L(q))+'</button>').join('')+'</div><p id="gut-note" aria-live="polite">'+e(L(gutNotes[gut]))+'</p></div>';}
function leafTools(){return `<div class="leaf-tools"><p>${T('點一下加1份；桌機也可拖進餐盤','Tap to add1; desktop can drag into the bowl')}</p><div class="leaf-buttons">${C.leaves.map((q,j)=>`<button data-leaf-add="${q.key}" draggable="true" aria-label="${e(T('加入','Add ')+L(q.title)+T('葉1份',' leaf,1 portion'))}"><svg aria-hidden="true" viewBox="0 0 60 42"><path d="M7 36Q10 5 51 7Q51 37 7 36Z" fill="${['#94dfe1','#efb96c','#b4d7a6'][j]}"/><path d="M7 36L47 10" stroke="#264956" stroke-width="3"/></svg><span>${e(L(q.title))}<b>＋1</b></span></button>`).join('')}</div><p id="leaf-status" aria-live="polite"></p><details id="leaf-traits"><summary>${T('看合成葉片成分','Synthetic leaf traits')}</summary><table><caption>${T('每份的自訂假設','Invented values per portion')}</caption><thead><tr><th>${T('葉片','Leaf')}</th><th>kJ</th><th>${T('吸收','Absorb')}</th><th>mL</th><th>${T('點','points')}</th></tr></thead><tbody>${C.leaves.map(q=>`<tr><th>${e(L(q.title))}</th><td>${q.gross}</td><td>${q.absorb}%</td><td>${q.water}</td><td>${q.load}</td></tr>`).join('')}</tbody></table></details></div>`;}
function leafMessage(kind,key){leafNotice={kind,key};$('#leaf-status').textContent=kind==='cap'?T(key.toUpperCase()+'葉已8份；餐盤和進度保留。',key.toUpperCase()+' leaf is at 8 portions; meal and progress kept.'):kind==='outside'?T('沒有放進餐盤；份數和進度保留。','Dropped outside the bowl; meal and progress kept.'):T('已加入'+key.toUpperCase()+'葉1份，從0重看分流。','Added 1 '+key.toUpperCase()+' leaf portion; flow restarts at 0.');}
