function bindProbe(){if(C.id==='C09'){bindKiwiTip();return;}if(C.id==='C04'){bindPlatBill();return;}if(C.id!=='B06')return;const area=$('#scene');let active=null;area.onpointerdown=ev=>{if(ev.pointerType!=='mouse'||!ev.target.closest('[data-probe]'))return;active=ev.pointerId;area.setPointerCapture(active);ev.preventDefault();};area.onpointermove=ev=>{if(ev.pointerId!==active)return;const rect=area.querySelector('svg').getBoundingClientRect(),x=(ev.clientX-rect.left)*720/rect.width,y=(ev.clientY-rect.top)*360/rect.height;setParam('x',(x-65)/50);setParam('y',(295-y)/30);};area.onpointerup=area.onpointercancel=()=>{active=null;};area.onkeydown=ev=>{if(!ev.target.closest('[data-probe]')||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key))return;ev.preventDefault();setParam(ev.key.includes('Left')||ev.key.includes('Right')?'x':'y',ev.key==='ArrowLeft'?p.x-.5:ev.key==='ArrowRight'?p.x+.5:ev.key==='ArrowUp'?p.y+.25:p.y-.25);area.querySelector('[data-probe]').focus();};}
