function rebuildTurnDetails(){const leafOpen=C.id==='D09'&&$('#leaf-traits')?.open;const ledgerOpen=C.id==='D05'&&$('#huddle-results')?.open;const opened=[...document.querySelectorAll('details.source')].map(x=>x.open);build();document.querySelectorAll('details.source').forEach((x,i)=>x.open=!!opened[i]);if(C.id==='D05'&&$('#huddle-results'))$('#huddle-results').open=!!ledgerOpen;if(C.id==='D09'&&$('#leaf-traits'))$('#leaf-traits').open=!!leafOpen;}
function changeLang(x){if(lang===x)return;lang=x;if(selected!==null)feedback=selected===C.answer?T('你的預測符合模型！試用對照模式驗證。','Your prediction matches the model. Test it in Compare.'):T('試著調整條件，再看結果能不能支持你的猜測。','Change conditions and check whether results support your guess.');rebuildTurnDetails();}
