function reset(){const restoreResetFocus=document.activeElement?.id==='reset';gut=0;cropLayer=-1;waterLayer=-1;caviLayer=-1;leafNotice=null;huddleNotice='';if(C.audio)stopSound();p={...C.defaults};running=false;time=0;phase=0;done=false;selected=null;feedback='';comparison=null;thermal={core:40,bill:32};water={volume:100,inside:0,outside:0,time:0};history=[];playedEcho=false;build();if(restoreResetFocus)$('#reset').focus({preventScroll:true});}
