function soundLabel(){const b=$('#listen-cue');if(b){b.textContent=muted?T('試聽合成音',C.id==='C08'?'Model sound':'Synthetic cue'):T('停止聲音','Stop sound');b.setAttribute('aria-pressed',String(!muted));}}
function stopSound(){soundGeneration++;if(soundTimer)clearTimeout(soundTimer);soundTimer=null;for(const n of soundNodes)try{n.stop();}catch(_){}soundNodes=[];muted=true;soundLabel();}
function playClickCue(r,generation){const start=audio.currentTime+.02,end=start+r.duration/1000+.055;soundNodes=[];for(const timeMs of r.times){const osc=audio.createOscillator(),g=audio.createGain(),t=start+timeMs/1000;osc.frequency.value=900;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.015,t+.002);g.gain.exponentialRampToValueAtTime(.0001,t+.025);osc.connect(g).connect(audio.destination);osc.start(t);osc.stop(t+.03);soundNodes.push(osc);}muted=false;soundLabel();soundTimer=setTimeout(()=>{if(generation===soundGeneration)stopSound();},(end-audio.currentTime)*1000+50);}
function playMothCue(r,generation){const start=audio.currentTime+.02,buffer=audio.createBuffer(1,Math.ceil(audio.sampleRate),audio.sampleRate),samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++){const t=i/audio.sampleRate,pt=r.points[Math.min(800,Math.floor(t*800))];samples[i]=.008*pt.recorded*Math.sin(2*Math.PI*700*t)*Math.min(1,t/.01,(1-t)/.01);}const source=audio.createBufferSource();source.buffer=buffer;source.connect(audio.destination);source.start(start);source.stop(start+1);soundNodes=[source];muted=false;soundLabel();soundTimer=setTimeout(()=>{if(generation===soundGeneration)stopSound();},1100);}
